package com.mohymods.kingdomsmp.profession;
import com.mohymods.kingdomsmp.economy.CommerceService;
import com.mohymods.kingdomsmp.contribution.ContributionService;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.neoforged.neoforge.items.ItemStackHandler;
/** Exact native millstone input drop, capability invalidation and real native wheat-to-flour processing. */
public final class MillingService {
 public static final String QUEST="kingdom_smp:engineer/a06",OUTPUT="create:wheat_flour";
 private MillingService(){}
 public record Input(BlockEntity machine,ServerPlayer player,ItemEntity entity,UUID source,int amount){}
 public record Impact(BlockEntity machine,MillingEvidence.Job job,int flour,boolean eligible){}
 public static BlockEntity machine(Object capability){try{var f=capability.getClass().getDeclaredField("this$0");f.setAccessible(true);return (BlockEntity)f.get(capability);}catch(ReflectiveOperationException|RuntimeException failure){return null;}}
 public static ItemStackHandler inventory(BlockEntity be,String name)throws ReflectiveOperationException{return (ItemStackHandler)be.getClass().getField(name).get(be);}
 private static boolean nativeMachine(BlockEntity be){return be!=null&&be.getLevel() instanceof ServerLevel level&&level.getServer().isSameThread()&&CreateCraftQuests.supported()&&be.getClass().getName().equals("com.simibubi.create.content.kinetics.millstone.MillstoneBlockEntity");}
 private static MillingEvidence.Cell cell(BlockEntity be){return new MillingEvidence.Cell(be.getLevel().dimension().location().toString(),be.getBlockPos().asLong());}
 private static boolean eligible(ServerPlayer p){if(!TreeQuestService.real(p)||ContributionService.kingdom(p.server).attainedTier()<4)return false;var store=CommerceService.initializedStore(p.server).orElse(null);if(store==null||store.quarantined())return false;var r=store.professions(p.getUUID());return r.isActive(Profession.ENGINEER)&&r.progressBand(Profession.ENGINEER)==ProfessionRank.APPRENTICE&&!r.track(Profession.ENGINEER).completedQuestIds().contains(QUEST);}
 public static boolean canFund(ServerPlayer p){return eligible(p);}
 private static boolean permitted(ServerPlayer p,BlockEntity be){var pos=be.getBlockPos();return be.getLevel()==p.serverLevel()&&p.serverLevel().hasChunkAt(pos)&&p.serverLevel().getBlockEntity(pos)==be&&p.distanceToSqr(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5)<=1024&&PlacementProtection.check(p.serverLevel(),p,pos,pos.above())==null;}
 private static boolean wheat(ItemStack stack){return stack.is(Items.WHEAT)&&ItemStack.isSameItemSameComponents(stack,new ItemStack(Items.WHEAT));}
 private static int flour(BlockEntity be)throws ReflectiveOperationException{int count=0;var inv=inventory(be,"outputInv");for(int n=0;n<inv.getSlots();n++){var s=inv.getStackInSlot(n);if(!s.isEmpty()&&BuiltInRegistries.ITEM.getKey(s.getItem()).toString().equals(OUTPUT)&&ItemStack.isSameItemSameComponents(s,new ItemStack(s.getItem())))count=Math.addExact(count,s.getCount());}return count;}
 public static ItemStack input(BlockEntity be){if(!nativeMachine(be))return null;try{return inventory(be,"inputInv").getStackInSlot(0).copy();}catch(ReflectiveOperationException|RuntimeException failure){TreeLifecycle.failure(((ServerLevel)be.getLevel()).getServer(),new IllegalStateException("Optional milling inventory unavailable",failure));return null;}}
 public static void changed(BlockEntity be,ItemStack before){if(before==null||!nativeMachine(be))return;var after=input(be);if(after!=null&&!ItemStack.matches(before,after))invalidate(be);}
 public static void invalidate(BlockEntity be){if(!nativeMachine(be))return;try{var d=MillingSavedData.get(((ServerLevel)be.getLevel()).getServer());d.proof().invalidate(cell(be));d.setDirty();}catch(RuntimeException failure){TreeLifecycle.failure(((ServerLevel)be.getLevel()).getServer(),failure);}}
 public static Input captureInput(Entity entity){if(!(entity instanceof ItemEntity item)||!(entity.level() instanceof ServerLevel level)||!level.getServer().isSameThread()||!(item.getOwner() instanceof ServerPlayer p))return null;try{var stack=item.getItem();if(!wheat(stack)||stack.getCount()<1||stack.getCount()>64||!eligible(p)||!NativeDropReceipts.funded(item))return null;for(var pos:List.of(item.blockPosition(),item.blockPosition().below())){var be=level.getBlockEntity(pos);if(!nativeMachine(be)||!permitted(p,be)||!inventory(be,"inputInv").getStackInSlot(0).isEmpty())continue;var funded=NativeDropReceipts.take(item);if(funded==null||!funded.player().equals(p.getUUID()))return null;return new Input(be,p,item,funded.entity(),funded.amount());}return null;}catch(ReflectiveOperationException|RuntimeException failure){TreeLifecycle.failure(level.getServer(),new IllegalStateException("Optional milling source unavailable",failure));return null;}}
 public static void inserted(Input source){if(source==null)return;var p=source.player();try{var input=inventory(source.machine(),"inputInv").getStackInSlot(0);if(!source.entity().isRemoved()||!source.entity().getUUID().equals(source.source())||!eligible(p)||!permitted(p,source.machine())||!wheat(input)||input.getCount()!=source.amount())return;var d=MillingSavedData.get(p.server);if(d.proof().start(cell(source.machine()),source.source(),p.getUUID(),source.amount()))d.setDirty();}catch(ReflectiveOperationException|RuntimeException failure){TreeLifecycle.failure(p.server,new IllegalStateException("Optional milling attribution unavailable",failure));}}
 public static Impact capture(BlockEntity be){if(!nativeMachine(be))return null;var level=(ServerLevel)be.getLevel();try{var d=MillingSavedData.get(level.getServer());var job=d.proof().job(cell(be)).orElse(null);if(job==null)return null;var input=inventory(be,"inputInv").getStackInSlot(0);if(!wheat(input)||input.getCount()!=job.remaining()){invalidate(be);return null;}float speed=((Number)be.getClass().getMethod("getSpeed").invoke(be)).floatValue();if(!Float.isFinite(speed)||speed==0)return null;var owner=level.getServer().getPlayerList().getPlayer(job.owner());return new Impact(be,job,flour(be),owner!=null&&eligible(owner)&&permitted(owner,be));}catch(ReflectiveOperationException|RuntimeException failure){TreeLifecycle.failure(level.getServer(),new IllegalStateException("Optional milling job unavailable",failure));return null;}}
 public static void commit(Impact impact){if(impact==null)return;var be=impact.machine();var level=(ServerLevel)be.getLevel();try{var input=inventory(be,"inputInv").getStackInSlot(0);int remaining=input.isEmpty()?0:wheat(input)?input.getCount():-1;if(remaining==impact.job().remaining())return;var d=MillingSavedData.get(level.getServer());int produced=flour(be)-impact.flour();if(remaining!=impact.job().remaining()-1||(produced<1||produced>3)){d.proof().invalidate(cell(be));d.setDirty();return;}var owner=level.getServer().getPlayerList().getPlayer(impact.job().owner());d.proof().advance(cell(be),impact.job(),impact.eligible()&&owner!=null&&eligible(owner)&&permitted(owner,be)?produced:0);d.setDirty();}catch(ReflectiveOperationException|RuntimeException failure){TreeLifecycle.failure(level.getServer(),new IllegalStateException("Optional milling output unavailable",failure));}}
 public static int count(ServerPlayer p){return MillingSavedData.get(p.server).proof().count(p.getUUID());}
 public static boolean ready(ServerPlayer p,int quantity){return CreateCraftQuests.supported()&&eligible(p)&&count(p)>=quantity;}
 public static String status(ServerPlayer p,int quantity){return !CreateCraftQuests.supported()?"Requires verified Create6.0.10. Existing records remain preserved.":count(p)+" / "+quantity+" native flour. Drop your wheat into an empty permitted millstone and supervise within32blocks. Keep its input unchanged; native partial batches persist. Permanently deliver matching plain flour at Ivo. Old/hopper stock gives no proof.";}
}
